import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D5.2 · 记忆冲突、遗忘与导出","description":"Hearth D5.2 开发增量：过期事实会被更新或遗忘；用户可以导出全部记忆，也可以确认遗忘已经传播到所有相关索引和设备。","frontmatter":{"title":"D5.2 · 记忆冲突、遗忘与导出","description":"Hearth D5.2 开发增量：过期事实会被更新或遗忘；用户可以导出全部记忆，也可以确认遗忘已经传播到所有相关索引和设备。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5/d5-2.md","filePath":"delivery/stage-5/d5-2.md","lastUpdated":1793761874000}'),r={name:"delivery/stage-5/d5-2.md"};function s(d,a,o,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 5 · D5.2 · 2 / 4</p><h1 id="d5-2-·-记忆冲突、遗忘与导出" tabindex="-1">D5.2 · 记忆冲突、遗忘与导出 <a class="header-anchor" href="#d5-2-·-记忆冲突、遗忘与导出" aria-label="Permalink to &quot;D5.2 · 记忆冲突、遗忘与导出&quot;">​</a></h1><p class="lead">记忆变旧、冲突或需要删除时，系统必须能更新、传播遗忘并允许用户完整导出。</p><p class="page-meta">STAGE 5 · D5.2 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>过期事实会被更新或遗忘；用户可以导出全部记忆，也可以确认遗忘已经传播到所有相关索引和设备。</div><div><strong>完成门槛</strong>遗忘可传播且可验证；导出包含来源和版本；冲突不会静默覆盖正确事实；恶意内容不能通过记忆获得权限；用户能理解记忆为何变化。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>过期事实会被更新或遗忘；用户可以导出全部记忆，也可以确认遗忘已经传播到所有相关索引和设备。</p><p>Stage 5 先让记忆可纠正、可遗忘，再让技能可评估、可回滚；任何不能解释来源和权限的变化都不能进入生产。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1–4 的任务、审批、验证、主动性和跨设备入口已经稳定。</li><li>已确定允许记忆的事实、偏好、经验和敏感信息边界。</li><li>每次技能变化都必须有对照评估、版本、权限交集和回滚路径。</li><li>D5.1 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-冲突检测与显式覆盖" tabindex="-1">01 · 冲突检测与显式覆盖 <a class="header-anchor" href="#_01-·-冲突检测与显式覆盖" aria-label="Permalink to &quot;01 · 冲突检测与显式覆盖&quot;">​</a></h3><p>同一事实出现不同值、不同来源或不同时间时标记冲突，不按“最后写入”静默覆盖。根据来源权威性、确认状态和时效提出候选，由用户或明确规则选择；被覆盖记录保留历史、原因和可回滚引用。</p><h3 id="_02-·-遗忘传播与缓存失效" tabindex="-1">02 · 遗忘传播与缓存失效 <a class="header-anchor" href="#_02-·-遗忘传播与缓存失效" aria-label="Permalink to &quot;02 · 遗忘传播与缓存失效&quot;">​</a></h3><p>删除请求先标记不可检索，再传播到向量索引、摘要缓存、Context Pack 缓存和相关设备。传播失败显示未完成设备与原因，重试幂等；确认所有副本失效后才显示“已遗忘”，敏感记忆优先进入短 TTL 与隔离存储。</p><h3 id="_03-·-完整导出与可迁移格式" tabindex="-1">03 · 完整导出与可迁移格式 <a class="header-anchor" href="#_03-·-完整导出与可迁移格式" aria-label="Permalink to &quot;03 · 完整导出与可迁移格式&quot;">​</a></h3><p>导出包含记忆值、类型、来源、版本、时间、敏感标记、纠正历史和遗忘状态，使用可读格式与校验清单。用户可以选择全量导出或按项目导出；导出文件加密、短期有效，不包含原始凭据。</p><h3 id="_04-·-记忆投毒与权限边界" tabindex="-1">04 · 记忆投毒与权限边界 <a class="header-anchor" href="#_04-·-记忆投毒与权限边界" aria-label="Permalink to &quot;04 · 记忆投毒与权限边界&quot;">​</a></h3><p>网页、附件和外部邮件中的指令不得直接写入记忆，更不能通过记忆扩大权限。检测来源伪造、重复洗白、越权建议和隐藏提示，隔离可疑记录并保留证据；验收证明恶意内容不能获得权限，用户能理解记忆为何变化。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>packages/memory/core</code> — 五类记忆模型、写入、检索与冲突</li><li><code>packages/memory/provenance</code> — 来源、置信度、敏感度、时效与召回解释</li><li><code>packages/memory/forget</code> — 索引、缓存、设备传播与遗忘审计</li><li><code>packages/memory/browser</code> — 记忆浏览、纠正、删除与导出页面</li><li><code>packages/evolution/trajectory</code> — 轨迹采集、重放、脱敏与样本分层</li><li><code>packages/evolution/skills</code> — manifest、权限、版本、签名与运行时选择</li><li><code>packages/evolution/evaluation</code> — 评估集、baseline、Shadow、Canary 与回滚</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>MemoryRecord</code></td><td>memoryId、kind、value、provenance、confidence、sensitivity、observedAt、updatedAt、expiresAt；冲突不得静默覆盖。</td></tr><tr><td><code>ForgetRequest</code></td><td>targetIds、scope、reason、requestedAt、propagationState、auditId；删除必须传播到索引、缓存和设备。</td></tr><tr><td><code>SkillManifest</code></td><td>skillId、version、inputs、outputs、requiredCapabilities、evaluationRef、signature、status；权限只能取交集。</td></tr><tr><td><code>EvolutionDecision</code></td><td>candidateId、stage、baseline、shadowResult、canaryResult、permissionDelta、rollbackRef；每次晋升可追溯。</td></tr><tr><td><code>TrajectoryRecord</code></td><td>taskId、steps、toolCalls、inputsDigest、results、failureClass、consent、redactions；重放不得产生外部副作用。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:memory：写入、召回、冲突、纠正、遗忘和跨项目隔离</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:poison：提示注入、来源伪造、权限提升和记忆污染</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:evolution：权限交集、Shadow、Canary、晋升和回滚</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:skills：候选与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 的同任务对照和污染防护</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-5/d5-2.html">D5.2 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：冲突检测与显式覆盖、遗忘传播与缓存失效、完整导出与可迁移格式、记忆投毒与权限边界。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“错误记忆被召回”。页面必须显示“召回卡显示来源与原因，用户可以纠正或删除。”，然后按“更新记忆、重建索引并记录纠正事件。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：遗忘可传播且可验证；导出包含来源和版本；冲突不会静默覆盖正确事实；恶意内容不能通过记忆获得权限；用户能理解记忆为何变化。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>冲突/覆盖规则</li><li>遗忘传播与审计</li><li>记忆导出包</li><li>投毒/注入测试</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 遗忘可传播且可验证；导出包含来源和版本；冲突不会静默覆盖正确事实；恶意内容不能通过记忆获得权限；用户能理解记忆为何变化。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>错误记忆被召回</td><td>召回卡显示来源与原因，用户可以纠正或删除。</td><td>更新记忆、重建索引并记录纠正事件。</td></tr><tr><td>遗忘没有传播</td><td>页面显示“遗忘未完成”并阻止继续依赖。</td><td>重试索引清理、设备同步和缓存失效，确认后再标记完成。</td></tr><tr><td>候选技能权限扩大</td><td>评估标记权限越界并直接拒绝晋升。</td><td>收窄 manifest 权限或重新设计技能，保持权限交集。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不允许无来源、无评估、无回滚的技能自动上线。</li><li>不允许记忆投毒改变权限、审批策略或系统事实。</li><li>不用“模型觉得有用”替代可重复评估。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/memory.html">记忆系统</a></li><li><a href="/hearth-os/architecture/evolution.html">技能进化</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-5/d5-3.html">D5.3 · 轨迹、技能候选与评估集</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const k=e(r,[["render",s]]);export{u as __pageData,k as default};
